"""Adversarial public-address tests; all keys/programs are synthetic public data."""

import unittest
from unittest.mock import patch
import transparent_address_guard as g

# Fixed public BIP173-style v0 vectors for Litecoin regtest HRP, generated by
# a separate reference encoder. They do not imply any address is spendable.
P2WPKH = 'rltc1qw508d6qejxtdg4y5r3zarvary0c5xw7k693xs3'
P2WSH = 'rltc1qyg3zyg3zyg3zyg3zyg3zyg3zyg3zyg3zyg3zyg3zyg3zyg3zyg3q3yy7ca'
MAIN = 'ltc1qw508d6qejxtdg4y5r3zarvary0c5xw7kgmn4n9'
TESTNET = 'tltc1qw508d6qejxtdg4y5r3zarvary0c5xw7klfsuq0'
MWEB_PREFIX_SHAPED = 'tmweb1qw508d6qejxtdg4y5r3zarvary0c5xw7k63hhv7'
V0_BECH32M = 'rltc1qw508d6qejxtdg4y5r3zarvary0c5xw7k0ep24n'


def ref_encode(hrp, witness_version, program, *, bech32m=False, append_5bit=()):
    """Independent test-only encoder, never used by production guard."""
    chars = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l'
    gens = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]
    result = [witness_version]
    accum, bits = 0, 0
    for item in program:
        accum = (accum << 8) | item
        bits += 8
        while bits >= 5:
            bits -= 5
            result.append((accum >> bits) & 31)
    if bits:
        result.append((accum << (5 - bits)) & 31)
    result.extend(append_5bit)
    chk = 1
    for value in ([ord(x) >> 5 for x in hrp] + [0]
                  + [ord(x) & 31 for x in hrp] + result + [0] * 6):
        top = chk >> 25
        chk = ((chk & 0x1ffffff) << 5) ^ value
        for idx, generator in enumerate(gens):
            if (top >> idx) & 1:
                chk ^= generator
    mod = chk ^ (0x2bc830a3 if bech32m else 1)
    values = result + [(mod >> (5 * (5 - i))) & 31 for i in range(6)]
    return hrp + '1' + ''.join(chars[x] for x in values)


class TransparentAddressGuards(unittest.TestCase):
    def denied(self, address, message=None):
        with self.assertRaises(g.AddressRefused) as err:
            g.classify_regtest_transparent(address)
        if message:
            self.assertIn(message, str(err.exception))

    def test_fixed_reference_p2wpkh_accepted_only_as_shape(self):
        result = g.classify_regtest_transparent(P2WPKH)
        self.assertEqual(result['scriptPubKeyHex'],
                         '0014751e76e8199196d454941c45d1b3a323f1433bd6')
        self.assertEqual(result['classification'],
                         'TRANSPARENT_REGTEST_V0_ADDRESS_SHAPE_ONLY')

    def test_fixed_reference_p2wsh_accepted_only_as_shape(self):
        result = g.classify_regtest_transparent(P2WSH)
        self.assertEqual(result['scriptPubKeyHex'], '0020' + '22' * 32)

    def test_reference_vectors_agree_with_independent_encoder(self):
        self.assertEqual(ref_encode('rltc', 0, bytes.fromhex('751e76e8199196d454941c45d1b3a323f1433bd6')), P2WPKH)
        self.assertEqual(ref_encode('rltc', 0, bytes.fromhex('22' * 32)), P2WSH)

    def test_success_never_confers_qualified_settlement(self):
        for candidate in [P2WPKH, P2WSH]:
            status = g.classify_regtest_transparent(candidate)
            for field in ['qualified', 'mwebExcludedInFullTransaction',
                          'canSign', 'canBroadcast', 'automaticSettlementSupported']:
                self.assertIs(status[field], False)

    def test_mainnet_address_refused_even_if_checksum_valid(self):
        self.denied(MAIN, 'not an LTC transparent regtest')

    def test_testnet_address_refused_even_if_checksum_valid(self):
        self.denied(TESTNET, 'not an LTC transparent regtest')

    def test_mweb_prefix_shaped_address_refused(self):
        self.denied(MWEB_PREFIX_SHAPED, 'not an LTC transparent regtest')

    def test_bitcoin_and_other_coins_refused(self):
        for hrp in ['bc', 'tb', 'bcrt', 'doge', 'eth', 'tmweb', 'ltc', 'tltc']:
            with self.subTest(hrp=hrp):
                self.denied(ref_encode(hrp, 0, bytes.fromhex('11' * 20)))

    def test_bech32m_checksum_for_v0_refused(self):
        self.denied(V0_BECH32M, 'checksum')

    def test_v1_witness_refused_even_if_checksum_valid(self):
        self.denied(ref_encode('rltc', 1, bytes.fromhex('11' * 32)), 'witness version')

    def test_short_v0_program_refused(self):
        self.denied(ref_encode('rltc', 0, bytes.fromhex('11' * 19)), 'program length')

    def test_long_v0_program_refused(self):
        self.denied(ref_encode('rltc', 0, bytes.fromhex('11' * 33)), 'program length')

    def test_padded_extra_five_bit_group_refused(self):
        self.denied(ref_encode('rltc', 0, bytes.fromhex('11' * 20), append_5bit=[0]), 'padding')

    def test_nonzero_leftover_padding_refused(self):
        candidate = ref_encode('rltc', 0, bytes.fromhex('11' * 20), append_5bit=[1])
        self.denied(candidate, 'padding')

    def test_single_character_mutations_refused(self):
        for pos in range(len(P2WPKH)):
            other = 'q' if P2WPKH[pos] != 'q' else 'p'
            bad = P2WPKH[:pos] + other + P2WPKH[pos + 1:]
            with self.subTest(pos=pos):
                self.denied(bad)

    def test_uppercase_and_mixed_case_refused(self):
        for bad in [P2WPKH.upper(), P2WPKH[:10].upper() + P2WPKH[10:],
                    P2WPKH.replace('rltc', 'rLtc')]:
            with self.subTest(bad=bad): self.denied(bad, 'case')

    def test_non_ascii_and_whitespace_refused(self):
        for bad in [' ' + P2WPKH, P2WPKH + '\n', P2WPKH.replace('r', 'ŕ', 1),
                    '\0' + P2WPKH]:
            with self.subTest(bad=repr(bad)): self.denied(bad)

    def test_bad_alphabet_refused(self):
        self.denied(P2WPKH[:-1] + 'b', 'alphabet')

    def test_wrong_separator_and_checksum_length_refused(self):
        for bad in ['rltc', 'rltc1', 'rltc1qq', 'rltc' + P2WPKH[5:], 'rltc11',
                    P2WPKH.replace('1', 'p', 1)]:
            with self.subTest(bad=bad): self.denied(bad)

    def test_overlong_and_overshort_refused(self):
        for bad in ['rltc1' + 'q' * 90, 'rltc1qq', '']:
            with self.subTest(bad=repr(bad)): self.denied(bad)

    def test_non_string_types_refused(self):
        for bad in [None, 1, False, b'rltc1', ['rltc'], {}]:
            with self.subTest(type=str(type(bad))): self.denied(bad)

    def test_pure_function_never_reads_or_writes_files(self):
        with patch('builtins.open', side_effect=AssertionError('file access forbidden')):
            self.assertTrue(g.classify_regtest_transparent(P2WPKH)['scriptPubKeyHex'])


if __name__ == '__main__':
    unittest.main()
